const $=s=>document.querySelector(s), money=n=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',maximumFractionDigits:2}).format(n/100), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed=()=>({locations:[{name:'Downtown',budget:1500000,spent:640000},{name:'West End',budget:1000000,spent:325000},{name:'Riverside',budget:1200000,spent:480000}],requests:[{id:1006,item:'Espresso grinder',cost:120000,reason:'Replace the aging grinder to keep up with the morning rush.',location:'Downtown',date:'2026-11-12',who:'Jamie Davis',status:'Pending',comments:[]},{id:1005,item:'Outdoor seating set',cost:245000,reason:'Four tables and eight chairs for the new patio.',location:'Riverside',date:'2026-11-18',who:'Morgan Lee',status:'Approved',comments:[{who:'Manager',text:'Approved for the patio opening.'}]},{id:1004,item:'Weekly packaging supplies',cost:38500,reason:'Compostable takeaway cups and lids.',location:'West End',date:'2026-11-09',who:'Jamie Davis',status:'Ordered',comments:[]},{id:1003,item:'Team training workshop',cost:65000,reason:'Barista training for the new team members.',location:'Downtown',date:'2026-11-15',who:'Alex Chen',status:'Pending',comments:[]},{id:1002,item:'Display shelving',cost:78000,reason:'Shelving for the retail coffee display.',location:'West End',date:'2026-11-05',who:'Morgan Lee',status:'Completed',comments:[]},{id:1001,item:'Premium speaker system',cost:95000,reason:'Upgrade the dining area speakers.',location:'Riverside',date:'2026-11-10',who:'Jamie Davis',status:'Declined',comments:[{who:'Manager',text:'Let’s revisit this next budget period.'}]}]});
let state;try{state=JSON.parse(localStorage.getItem('clearspend-v1'))}catch{}if(!state?.locations||!state?.requests)state=seed();state.adjustments??=[];let historyContext=null,historyStatus='All',returnToHistory=false;let role='employee',activeId=null,view='Overview',fromInbox=false,inboxMode='active',chartPeriod='monthly',selectedBar=null;const committed=r=>['Approved','Ordered'].includes(r.status), totals=loc=>{const rs=state.requests.filter(r=>r.location===loc.name);const adjustments=(state.adjustments||[]).filter(a=>!a.removed&&a.location===loc.name);const budget=loc.budget+adjustments.reduce((sum,a)=>sum+(a.type==='add'?a.cost:a.type==='withdraw'?-a.cost:0),0);const spent=loc.spent+adjustments.reduce((sum,a)=>sum+(a.type==='expense'?a.cost:a.type==='refund'?-a.cost:0),0)+rs.filter(r=>r.status==='Completed').reduce((a,r)=>a+r.cost,0),reserved=rs.filter(committed).reduce((a,r)=>a+r.cost,0);return{budget,spent,reserved,available:budget-spent-reserved}};
