function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function render(){let t=state.locations.map(totals).reduce((a,t)=>{Object.keys(a).forEach(k=>a[k]+=t[k]);return a},{budget:0,spent:0,reserved:0,available:0});$('#stats').innerHTML=role==='manager'?[['Total budget',t.budget,'Across all three locations'],['Actual spending',t.spent,'Purchases + opening and external spend'],['Approved commitments',t.reserved,'Approved and ordered purchases'],['Available to spend',t.available,'Budget − spent − committed']].map(([label,n,note])=>`<div class="stat"><small>${label}</small><strong class="${n<0?'over':''}">${money(n)}</strong><span>${note}</span></div>`).join(''):employeeSummary();$('#locations').innerHTML=role==='manager'?state.locations.map(l=>{let t=totals(l);return `<article class="location"><div class="location-top"><div><span class="pin">⌖</span><h3>${esc(l.name)}</h3></div><span class="subtle">Oak & Ember</span></div><div class="available"><strong class="${t.available<0?'over':''}">${money(t.available)}</strong>available to spend</div><div class="bar"><i style="width:${Math.max(0,Math.min(100,t.spent/Math.max(1,t.budget)*100))}%"></i><b style="width:${Math.min(Math.max(0,100-t.spent/Math.max(1,t.budget)*100),t.reserved/Math.max(1,t.budget)*100)}%"></b></div><div class="legend"><span>● Spent ${money(t.spent)}</span><span>● Committed ${money(t.reserved)}</span></div><div class="location-bottom"><span>Total budget</span><strong>${money(t.budget)}</strong></div></article>`}).join(''):'';let rs=state.requests.filter(r=>(role==='manager'||r.who==='Jamie Davis')&&($('#filter').value==='All statuses'||r.status===$('#filter').value));$('#count').textContent=rs.length;$('#rows').innerHTML=rs.map(r=>`<tr><td><strong>${esc(r.item)}</strong><small>${role==='manager'?esc(r.who)+' · ':''}${r.kind==='direct'?'PUR':'REQ'}-${r.id}${r.kind==='direct'?' · Direct purchase':''}</small></td><td>${esc(r.location)}</td><td><strong>${money(r.cost)}</strong></td><td>${esc(r.date)}</td><td><span class="badge ${r.status}">${r.status}</span></td><td><button data-open="${r.id}">View ↗</button></td></tr>`).join('');$('#empty').hidden=rs.length>0;$('#request-subtitle').textContent=role==='manager'?'Good decisions start with the full picture.':'Your requests, from first idea to final receipt.';document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{fromInbox=false;returnToHistory=false;detail(Number(b.dataset.open))});updateView()}
function openModal(html){$('#modal-body').innerHTML=html;$('#modal').setAttribute('aria-labelledby','dialog-title');$('#modal').showModal();$('#modal-body').querySelector('[data-close]').onclick=()=>$('#modal').close()}
const modalHead=title=>`<div class="modal-head"><h2 id="dialog-title">${title}</h2><button data-close aria-label="Close dialog">×</button></div>`;
$('#new').onclick=()=>{returnToHistory=false;fromInbox=false;$('#modal').classList.remove('inbox-dialog');const direct=role==='manager';openModal(modalHead(direct?'Record a purchase':'Request a purchase')+`<p>${direct?'Log a purchase you have already made. It will count toward actual spending immediately.':'Tell your manager what you need and why.'}</p><form id="request-form"><label for="item">Item or service</label><input id="item" name="item" required maxlength="100" placeholder="e.g. Espresso grinder"><div class="form-grid"><div><label for="cost">${direct?'Amount paid (CAD)':'Estimated total (CAD)'}</label><input id="cost" name="cost" type="number" min="0.01" max="1000000" step="0.01" required placeholder="0.00"></div><div><label for="location">Location</label><select id="location" name="location">${state.locations.map(l=>`<option>${l.name}</option>`).join('')}</select></div></div><label for="reason">${direct?'Purchase notes':'Why do you need it?'}</label><textarea id="reason" name="reason" required maxlength="1500" placeholder="${direct?'What was purchased and why?':'Help your manager understand the purchase.'}"></textarea><label for="date">${direct?'Purchase date':'Needed by'}</label><input id="date" name="date" type="date" required><label for="link">Product or quote link (optional)</label><input id="link" name="link" type="url" placeholder="https://example.com/product"><div class="actions"><button type="submit" class="primary">${direct?'Record purchase ✓':'Submit request ↗'}</button></div></form>`);$('#request-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);if(!String(f.get('item')).trim()||!String(f.get('reason')).trim())return toast('Please include an item and reason.');state.requests.unshift({requestedOn:today(),id:Math.max(1000,...state.requests.map(r=>r.id))+1,item:String(f.get('item')).trim(),cost:Math.round(Number(f.get('cost'))*100),location:f.get('location'),reason:String(f.get('reason')).trim(),date:f.get('date'),link:f.get('link'),purchasedOn:direct?f.get('date'):null,who:direct?'Manager':'Jamie Davis',kind:direct?'direct':'request',status:direct?'Completed':'Pending',comments:direct?[{who:'Manager',text:'Purchase recorded directly as completed.'}]:[]});$('#filter').value='All statuses';persist();$('#modal').close();toast(direct?'Purchase recorded. Actual spending has been updated.':'Request submitted. Switch to Manager to review it.')}};
function detail(id){$('#modal').classList.remove('inbox-dialog');activeId=id;let r=state.requests.find(r=>r.id===id);if(!r||(role==='employee'&&r.who!=='Jamie Davis'))return;let t=totals(state.locations.find(l=>l.name===r.location));let buttons=[];if(role==='manager')buttons.push([r.status==='Removed'?'Restore':'Remove',r.status==='Removed'?'Restore record':'Remove record','danger']);if(role==='manager'&&r.status==='Pending')buttons.push(['Approved','Approve request','primary'],['Declined','Decline','danger']);if(role==='manager'&&r.status==='Approved')buttons.push(['Ordered','Mark as ordered','primary']);if(role==='manager'&&['Approved','Ordered'].includes(r.status))buttons.push(['Completed','Mark completed','primary']);if((role==='manager'||r.who==='Jamie Davis')&&['Pending','Approved','Ordered'].includes(r.status))buttons.push(['Canceled','Cancel request','danger']);openModal((returnToHistory?'<button id="back-history" class="back-inbox">← Period history</button>':'')+(fromInbox?'<button id="back-inbox" class="back-inbox">← Request inbox</button>':'')+modalHead(esc(r.item))+`<span class="badge ${r.status}">${r.status}</span><div class="detail-grid"><div><small>${r.kind==='direct'?'Amount paid':'Estimated total'}</small><strong>${money(r.cost)}</strong></div><div><small>Location</small>${esc(r.location)}</div><div><small>${r.kind==='direct'?'Purchased by':'Requested by'}</small>${esc(r.who)}</div><div><small>${r.kind==='direct'?'Purchase date':'Needed by'}</small>${esc(r.date)}</div></div><p>${esc(r.reason)}</p>${r.link&&/^https?:\/\//i.test(r.link)?`<p><a href="${esc(r.link)}" target="_blank" rel="noopener noreferrer">View product or quote ↗</a></p>`:''}${role==='manager'?`<div class="context" style="margin-top:18px">Available at ${esc(r.location)}: <strong>${money(t.available)}</strong>${r.status==='Pending'?`<br>After approval: <strong class="${t.available-r.cost<0?'over':''}">${money(t.available-r.cost)}</strong>${t.available<r.cost?'<br>This request exceeds the available budget. Approval is blocked.':''}`:''}${['Approved','Ordered'].includes(r.status)?'<br>This purchase is reserved in the budget. Completing it moves the same amount to actual spending.':''}</div>`:''}<h3 style="font-size:14px;margin-top:24px">Conversation</h3><div>${r.comments.length?r.comments.map(c=>`<div class="comment"><small>${esc(c.who)}</small>${esc(c.text)}</div>`).join(''):'<p>No comments yet.</p>'}</div><form id="comment-form"><label for="comment">Add a comment</label><textarea id="comment" required maxlength="1500" placeholder="Ask a question or leave context…"></textarea><button style="margin-top:8px">Post comment</button></form><div class="actions">${buttons.map(([status,label,cls])=>`<button data-status="${status}" class="${cls}">${label}</button>`).join('')}</div>`);if($('#back-history'))$('#back-history').onclick=()=>showPeriodHistory();if($('#back-inbox'))$('#back-inbox').onclick=showInbox;$('#comment-form').onsubmit=e=>{e.preventDefault();const text=$('#comment').value.trim();if(!text)return; r.comments.push({who:role==='manager'?'Manager':'Jamie Davis',text});persist();$('#modal').close();detail(id)};document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>transition(id,b.dataset.status))}
function transition(id,next){const r=state.requests.find(r=>r.id===id);if(['Remove','Restore'].includes(next)){changeRecord(r,next);return}const allowed={Pending:['Approved','Declined','Canceled'],Approved:['Ordered','Completed','Canceled'],Ordered:['Completed','Canceled']};if(!allowed[r.status]?.includes(next))return;if(role!=='manager'&&(next!=='Canceled'||r.who!=='Jamie Davis'))return;if(next==='Approved'&&totals(state.locations.find(l=>l.name===r.location)).available<r.cost)return toast('Not enough available budget for this purchase.');r.status=next;if(next==='Completed')r.purchasedOn=new Date().toLocaleDateString('en-CA',{timeZone:'America/Toronto'});r.comments.push({who:role==='manager'?'Manager':'Jamie Davis',text:'Status changed to '+next.toLowerCase()+'.'});persist();$('#modal').close();if(returnToHistory)showPeriodHistory();else if(fromInbox)showInbox();toast(next==='Completed'?'Purchase completed. Commitment moved to actual spending.':next==='Canceled'?'Request canceled. Any reserved budget has been released.':'Request '+next.toLowerCase()+'.')}
$('#role').value=role;$('#role').onchange=e=>{role=e.target.value;view='Overview';$('#filter').value='All statuses';$('#modal').close();fromInbox=false;returnToHistory=false;render()};$('#filter').onchange=render;$('#reset').onclick=()=>{if(confirm('Reset all purchases and comments to the fictional sample data?')){state=seed();persist();toast('Sample data restored.')}};document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{view=b.dataset.nav;updateView()});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')&&(e.clientX<$('#modal').getBoundingClientRect().left||e.clientX>$('#modal').getBoundingClientRect().right||e.clientY<$('#modal').getBoundingClientRect().top||e.clientY>$('#modal').getBoundingClientRect().bottom))$('#modal').close()});render();

function employeeSummary(){const mine=state.requests.filter(r=>r.who==='Jamie Davis');return [['Your requests',mine.length,'Only purchases you submitted'],['Awaiting review',mine.filter(r=>r.status==='Pending').length,'Your manager will review these'],['Ready to purchase',mine.filter(r=>r.status==='Approved').length,'Approved and ready for the next step'],['In progress',mine.filter(r=>r.status==='Ordered').length,'Your ordered purchases']].map(([label,count,note])=>`<div class="stat"><small>${label}</small><strong>${count}</strong><span>${note}</span></div>`).join('')}
function updateView(){const employee=role==='employee';if(employee&&['Funds','Locations'].includes(view))view='Overview';$('#funds-page').hidden=employee||view!=='Funds';if(!employee)renderFunds();$('.spending-tracker').hidden=employee||['Requests','Funds'].includes(view);renderSpending();$('.manager-inbox').hidden=employee||view!=='Requests';const current=state.requests.filter(r=>r.kind!=='direct'&&['Pending','Approved','Ordered'].includes(r.status));$('#inbox-summary').textContent=current.length+' active requests · '+current.filter(r=>r.status==='Pending').length+' awaiting your review';$('#new').textContent=employee?'＋ New request':'＋ Record purchase';syncStatusFilter();if(employee&&view==='Locations')view='Overview';document.body.classList.toggle('employee-view',employee);document.querySelectorAll('[data-nav]').forEach(b=>{b.hidden=employee&&['Locations','Funds'].includes(b.dataset.nav);b.classList.toggle('active',b.dataset.nav===view);if(b.dataset.nav==='Requests')b.textContent=employee?'↗  My requests':'↗  Purchase requests'});$('#crumb').textContent=employee?(view==='Overview'?'My workspace':'My requests'):view;$('#title').textContent=employee?(view==='Overview'?'What do you need, Jamie?':'Your requests. Every step of the way.'):(view==='Overview'?'A clear view of every purchase.':view==='Requests'?'Every request. One clear path.':'Room to spend. Space to grow.');$('#subtitle').textContent=employee?'Request what you need, follow its progress, and talk with your manager.':view==='Locations'?'Location budgets that include what you’ve already promised.':'From the first request to the final receipt. All in one place.';$('.eyebrow').textContent=employee?'YOUR PERSONAL WORKSPACE':'SPEND WITH CONFIDENCE';$('.stats').hidden=['Requests','Funds'].includes(view);$('.locations').hidden=employee||['Requests','Funds'].includes(view);$('.locations').previousElementSibling.hidden=employee||['Requests','Funds'].includes(view);$('.requests').hidden=['Locations','Funds'].includes(view);$('.requests h2').firstChild.textContent=employee?'My purchase requests ':'Purchase requests ';$('.company small').textContent=employee?'Jamie Davis · Employee':'3 locations · Demo business';$('#reset').hidden=employee;if(view==='Funds'){$('#title').textContent='Every money movement, accounted for.';$('#subtitle').textContent='Track funds and expenses outside the purchase request workflow.';$('#new').hidden=true}else $('#new').hidden=false;$('.employee-guide').hidden=!employee||view!=='Overview';$('.notice span').innerHTML=employee?'<strong>Employee demo.</strong> You see your own requests. Company budgets and team spending are in the manager view. The role switcher is for this demo only.':'<strong>Manager demo.</strong> Review team purchases and location budgets. The role switcher is for this demo only.'}

const statuses=['All statuses','Pending','Approved','Ordered','Completed','Declined','Canceled'];
$('#filter-menu').innerHTML=statuses.map(status=>`<button type="button" class="filter-option ${status==='All statuses'?'':status}" data-filter-status="${status}"><span class="status-dot"></span>${status}<span class="filter-check" aria-hidden="true">✓</span></button>`).join('');
function syncStatusFilter(){const selected=$('#filter').value;$('#filter-toggle').className=selected==='All statuses'?'':selected;$('#filter-toggle').innerHTML=`<span class="status-dot"></span>${esc(selected)}<span>⌄</span>`;document.querySelectorAll('[data-filter-status]').forEach(b=>{const chosen=b.dataset.filterStatus===selected;b.classList.toggle('selected',chosen);b.setAttribute('aria-pressed',String(chosen))})}
function closeFilter(){ $('#filter-menu').hidden=true;$('#filter-toggle').setAttribute('aria-expanded','false') }
$('#filter-toggle').onclick=()=>{const open=$('#filter-menu').hidden;$('#filter-menu').hidden=!open;$('#filter-toggle').setAttribute('aria-expanded',String(open));if(open)$('#filter-menu button.selected')?.focus()};
document.querySelectorAll('[data-filter-status]').forEach(b=>b.onclick=()=>{$('#filter').value=b.dataset.filterStatus;closeFilter();render();$('#filter-toggle').focus()});
document.addEventListener('click',e=>{if(!e.target.closest('.status-filter'))closeFilter()});
$('.status-filter').addEventListener('keydown',e=>{if(e.key==='Escape'){closeFilter();$('#filter-toggle').focus()}if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)&&!$('#filter-menu').hidden){e.preventDefault();const options=[...$('#filter-menu').querySelectorAll('button')],index=options.indexOf(document.activeElement);const next=e.key==='Home'?0:e.key==='End'?options.length-1:(index+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;options[next].focus()}});syncStatusFilter();

$('#open-inbox').onclick=()=>{returnToHistory=false;inboxMode='active';showInbox()};
function showInbox(){if(role!=='manager')return;fromInbox=true;if($('#modal').open)$('#modal').close();const all=state.requests.filter(r=>r.kind!=='direct'),active=all.filter(r=>['Pending','Approved','Ordered'].includes(r.status)),pending=all.filter(r=>r.status==='Pending');let list=inboxMode==='pending'?pending:inboxMode==='all'?all:active;list=[...list].sort((a,b)=>(a.status==='Pending'?0:1)-(b.status==='Pending'?0:1)||a.date.localeCompare(b.date));$('#modal').classList.add('inbox-dialog');openModal(modalHead('Request inbox')+`<p>Everything your team is asking for. Review the details and decide what happens next.</p><div class="inbox-tabs"><button data-inbox-mode="active" aria-pressed="${inboxMode==='active'}">Active requests <b>${active.length}</b></button><button data-inbox-mode="pending" aria-pressed="${inboxMode==='pending'}">Needs review <b>${pending.length}</b></button><button data-inbox-mode="all" aria-pressed="${inboxMode==='all'}">All requests <b>${all.length}</b></button></div><div class="inbox-list">${list.length?list.map(r=>`<article class="inbox-card"><div class="inbox-card-head"><div><small>REQ-${r.id} · ${esc(r.location)}</small><h3>${esc(r.item)}</h3></div><strong>${money(r.cost)}</strong></div><div class="inbox-meta"><span>${esc(r.who)}</span><span>Needed by ${esc(r.date)}</span><span class="badge ${r.status}">${r.status}</span></div><p>${esc(r.reason)}</p><div class="inbox-card-bottom"><span>${r.comments.length} ${r.comments.length===1?'update':'updates'}</span><button class="${r.status==='Pending'?'primary':''}" data-review="${r.id}">${r.status==='Pending'?'Review request':'View details'} ↗</button></div></article>`).join(''):'<div id="empty-inbox">You’re all caught up. No requests in this view.</div>'}</div>`);document.querySelectorAll('[data-inbox-mode]').forEach(b=>b.onclick=()=>{inboxMode=b.dataset.inboxMode;showInbox()});document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{$('#modal').close();detail(Number(b.dataset.review))})}
$('#modal').addEventListener('close',()=>{if(!$('#modal').open)$('#modal').classList.remove('inbox-dialog')});

function spendingEntries(){const entries=[];const weights=[8,9,9,10,10,11,10,11,10,12];for(const l of state.locations){for(const year of [2024,2025,2026]){const total=Math.round(l.spent*(year===2024?.76:year===2025?.88:1));let assigned=0;weights.forEach((weight,index)=>{const cost=index===9?total-assigned:Math.round(total*weight/100);assigned+=cost;entries.push({location:l.name,date:year+'-'+String(index+1).padStart(2,'0')+'-15',cost,item:'Opening spending · '+l.name,source:'Opening history'})})}}for(const r of state.requests.filter(r=>r.status==='Completed'))entries.push({location:r.location,date:r.purchasedOn||r.date,cost:r.cost,item:r.item,source:'Purchase',requestId:r.id});for(const a of (state.adjustments||[]).filter(a=>!a.removed&&['expense','refund'].includes(a.type)))entries.push({location:a.location,date:a.date,cost:a.type==='refund'?-a.cost:a.cost,item:a.reason,source:a.type==='refund'?'External refund':'External expense'});return entries}
function renderSpending(){const availableYears=[...new Set([2024,2025,2026,...spendingEntries().map(e=>Number(e.date.slice(0,4))),...state.requests.flatMap(r=>[r.requestedOn,r.purchasedOn,r.date].filter(Boolean).map(d=>Number(d.slice(0,4))))])].filter(Number.isFinite).sort((a,b)=>a-b);const retainedYear=$('#chart-year').value;$('#chart-year').innerHTML=[...availableYears].reverse().map(y=>`<option ${String(y)===retainedYear?'selected':''}>${y}</option>`).join('');const year=Number($('#chart-year').value),location=$('#chart-location').value;$('#chart-year').hidden=chartPeriod==='yearly';document.querySelectorAll('[data-period]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.period===chartPeriod)));const months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];let buckets=chartPeriod==='monthly'?months.map((label,i)=>({label,key:year+'-'+String(i+1).padStart(2,'0'),total:0})):chartPeriod==='quarterly'?[1,2,3,4].map(q=>({label:'Q'+q,key:year+'-Q'+q,total:0})):availableYears.map(y=>({label:String(y),key:String(y),total:0}));for(const e of spendingEntries()){if(location!=='All locations'&&e.location!==location)continue;const [y,m]=e.date.split('-').map(Number);const key=chartPeriod==='monthly'?e.date.slice(0,7):chartPeriod==='quarterly'?y+'-Q'+Math.ceil(m/3):String(y);const bucket=buckets.find(b=>b.key===key);if(bucket)bucket.total+=e.cost}const total=buckets.reduce((a,b)=>a+b.total,0),max=Math.max(100,...buckets.map(b=>Math.abs(b.total))),scale=Math.ceil(max/50000)*50000,hasNegative=buckets.some(b=>b.total<0);$('#chart-total').textContent=money(total);$('#chart-total-label').textContent=(chartPeriod==='yearly'?availableYears[0]+'–'+availableYears.at(-1):year)+' · '+location;$('#spending-chart').innerHTML=`<div class="chart-axis"><span>${money(scale)}</span><span>${hasNegative?'$0':money(scale/2)}</span><span>${hasNegative?money(-scale):'$0'}</span></div><div class="chart-plot ${hasNegative?'signed-chart':''}">${buckets.map((b,i)=>`<button class="spending-bar ${selectedBar===b.key?'chosen':''}" data-bucket="${i}" aria-label="${b.label}: ${money(b.total)}" title="${b.label}: ${money(b.total)}"><span class="bar-tooltip" role="tooltip">${b.label}<strong>${money(b.total)}</strong><small>Click to explore history</small></span><span class="bar-fill" style="${hasNegative?'position:absolute;'+(b.total<0?'top:50%;':'bottom:50%;'):''}height:${b.total?Math.max(1,Math.abs(b.total)/scale*(hasNegative?50:100)):0}%"></span><span class="bar-label">${b.label}</span></button>`).join('')}</div>`;const chosen=buckets.find(b=>b.key===selectedBar);$('#chart-detail').textContent=chosen?chosen.label+' · '+money(chosen.total)+' actual spending':total===0?'No completed purchases for this period.':'Hover for an exact amount. Click to open period history.';document.querySelectorAll('[data-bucket]').forEach(b=>b.onclick=()=>{const bucket=buckets[Number(b.dataset.bucket)];selectedBar=bucket.key;historyContext={key:bucket.key,label:chartPeriod==='yearly'?bucket.label:bucket.label+' '+year,period:chartPeriod,location,total:bucket.total};historyStatus='All';returnToHistory=true;fromInbox=false;renderSpending();showPeriodHistory()})}
document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{chartPeriod=b.dataset.period;selectedBar=null;renderSpending()});$('#chart-year').onchange=$('#chart-location').onchange=()=>{selectedBar=null;renderSpending()};

function today(){return new Date().toLocaleDateString('en-CA',{timeZone:'America/Toronto'})}
function inHistoryPeriod(date){if(!date||!historyContext)return false;const [y,m]=date.split('-').map(Number);return (historyContext.period==='monthly'?date.slice(0,7):historyContext.period==='quarterly'?y+'-Q'+Math.ceil(m/3):String(y))===historyContext.key}
function showPeriodHistory(){if(role!=='manager'||!historyContext)return;returnToHistory=true;fromInbox=false;if($('#modal').open)$('#modal').close();const context=historyContext;const all=state.requests.filter(r=>(context.location==='All locations'||r.location===context.location)&&inHistoryPeriod(historyRecordDate(r)));const entries=spendingEntries().filter(e=>(context.location==='All locations'||e.location===context.location)&&inHistoryPeriod(e.date));const total=entries.reduce((sum,e)=>sum+e.cost,0);const tabs=['All','Pending','Approved','Ordered','Completed','Declined','Canceled','Removed','Spending breakdown'];const list=all.filter(r=>historyStatus==='All'||r.status===historyStatus);$('#modal').classList.add('inbox-dialog');openModal(modalHead(esc(context.label)+' · Purchase history')+`<div class="period-summary"><strong>${money(total)}</strong><span>Actual spending · ${esc(context.location)}</span></div><p class="period-explanation">Completed purchases use the purchase date; other requests use the submission date. Older demo requests use their needed-by date. Only completed purchases and external spending affect the chart.</p><div class="history-tools"><div class="history-views" role="group" aria-label="History view"><button data-history-view="requests" aria-pressed="${historyStatus!=='Spending breakdown'}">Purchase requests <span>${all.length}</span></button><button data-history-view="spending" aria-pressed="${historyStatus==='Spending breakdown'}">Spending breakdown <span>${entries.length}</span></button></div>${historyStatus!=='Spending breakdown'?`<details class="history-status-picker"><summary class="${historyStatus==='All'?'':historyStatus}"><span class="status-dot"></span>${historyStatus==='All'?'All statuses':historyStatus}<span class="picker-chevron">⌄</span></summary><div class="history-status-options" role="group" aria-label="Request status">${tabs.filter(t=>t!=='Spending breakdown').map(t=>`<button data-history-status="${t}" class="${t==='All'?'':t}" aria-pressed="${historyStatus===t}"><span class="status-dot"></span><span>${t==='All'?'All statuses':t}</span><b>${t==='All'?all.length:all.filter(r=>r.status===t).length}</b><span class="selection-check">${historyStatus===t?'✓':''}</span></button>`).join('')}</div></details>`:''}</div><div class="history-results-label">${historyStatus==='Spending breakdown'?entries.length+' spending '+(entries.length===1?'entry':'entries'):list.length+' '+(historyStatus==='All'?'purchase':historyStatus.toLowerCase())+' '+(list.length===1?'record':'records')}</div><div class="inbox-list">${historyStatus==='Spending breakdown'?entries.map(e=>`<article class="history-entry"><div><strong>${esc(e.item)}</strong><small>${esc(e.source)} · ${esc(e.location)} · ${esc(e.date)}</small></div><strong>${money(e.cost)}</strong></article>`).join('')||'<p class="empty-history">No spending in this period.</p>':list.map(r=>`<article class="inbox-card"><div class="inbox-card-head"><div><small>${r.kind==='direct'?'PUR':'REQ'}-${r.id} · ${esc(r.location)}</small><h3>${esc(r.item)}</h3></div><strong>${money(r.cost)}</strong></div><div class="inbox-meta"><span>${esc(r.who)}</span><span>${esc(historyRecordDate(r))}</span><span class="badge ${r.status}">${r.status}</span></div><p>${esc(r.reason)}</p><div class="inbox-card-bottom"><span>${r.kind==='direct'?'Direct purchase':'Purchase request'}</span><button data-history-review="${r.id}">View details ↗</button></div></article>`).join('')||'<p class="empty-history">No matching requests in this period. Check Spending breakdown for opening history or external expenses.</p>'}</div>`);document.querySelectorAll('[data-history-view]').forEach(b=>b.onclick=()=>{historyStatus=b.dataset.historyView==='spending'?'Spending breakdown':'All';showPeriodHistory()});document.querySelectorAll('[data-history-status]').forEach(b=>b.onclick=()=>{historyStatus=b.dataset.historyStatus;showPeriodHistory()});document.querySelectorAll('[data-history-review]').forEach(b=>b.onclick=()=>{$('#modal').close();detail(Number(b.dataset.historyReview))})}
function changeRecord(r,action){if(role!=='manager'||!r)return;$('#modal').close();$('#modal').classList.remove('inbox-dialog');const restoring=action==='Restore';openModal(modalHead(restoring?'Restore purchase record?':'Remove purchase record?')+`<p>${restoring?'This restores the previous status and its budget impact.':'This removes this record from active requests, commitments, and spending totals. It does not cancel an order with a vendor or issue a refund. You can restore it later.'}</p><form id="record-change"><label for="change-note">Reason</label><textarea id="change-note" required maxlength="1500" placeholder="Explain this change for the record."></textarea><div class="actions"><button class="primary">${restoring?'Restore record':'Remove record'}</button><button type="button" id="keep-record">Keep as is</button></div></form>`);$('#keep-record').onclick=()=>{$('#modal').close();detail(r.id)};$('#record-change').onsubmit=e=>{e.preventDefault();const reason=$('#change-note').value.trim();if(!reason)return;const next=restoring?r.previousStatus:'Removed';if(restoring&&['Approved','Ordered'].includes(next)&&totals(state.locations.find(l=>l.name===r.location)).available<r.cost)return toast('Not enough available budget to restore this purchase.');if(!restoring)r.previousStatus=r.status;r.status=next;r.comments.push({who:'Manager',text:(restoring?'Restored':'Removed')+': '+reason});persist();$('#modal').close();if(returnToHistory)showPeriodHistory();else if(fromInbox)showInbox();toast(restoring?'Record restored. Totals updated.':'Record removed from totals. You can restore it from its details.')}}
function renderFunds(){const adjustments=state.adjustments||[];$('#funds-page').innerHTML=`<div class="funds-intro"><div><h2>Funds & adjustments</h2><p>Record outside money movements for each location. These are tracking entries; no money is transferred.</p></div><button class="primary" id="add-adjustment">＋ Add adjustment</button></div><div class="funds-rules"><div><strong>Add / withdraw funds</strong><p>Changes the location’s available budget without creating an expense.</p></div><div><strong>External expense / refund</strong><p>Changes actual spending and the chart without creating a purchase request.</p></div></div><div class="table-wrap"><table><thead><tr><th>DATE</th><th>LOCATION / REASON</th><th>TYPE</th><th>AMOUNT</th><th></th></tr></thead><tbody>${adjustments.map(a=>`<tr><td>${esc(a.date)}</td><td><strong>${esc(a.location)}</strong><small>${esc(a.reason)}</small></td><td>${esc(adjustmentLabel(a.type))}${a.removed?' · Reversed':''}</td><td>${['withdraw','expense'].includes(a.type)?'−':'+'}${money(a.cost)}</td><td><button data-reverse="${a.id}" ${a.removed?'disabled':''}>${a.removed?'Reversed':'Reverse entry'}</button></td></tr>`).join('')}</tbody></table>${!adjustments.length?'<p class="empty-history">No outside adjustments yet. Add your first entry to keep the budget up to date.</p>':''}</div>`;$('#add-adjustment').onclick=adjustmentForm;document.querySelectorAll('[data-reverse]').forEach(b=>b.onclick=()=>{const a=state.adjustments.find(a=>String(a.id)===b.dataset.reverse);if(!a||a.removed)return;if(budgetAfterReversal(a)<0)return toast('Reverse the related withdrawal first. This reversal would make the total budget negative.');a.removed=true;persist();toast('Adjustment reversed. Budget and chart updated.')})}
function adjustmentLabel(type){return {add:'Funds added',withdraw:'Funds withdrawn',expense:'External expense',refund:'External refund'}[type]}
function adjustmentForm(){if(role!=='manager')return;returnToHistory=false;fromInbox=false;$('#modal').classList.remove('inbox-dialog');openModal(modalHead('Record an adjustment')+`<form id="adjustment-form"><label for="adjustment-type">Money movement</label><select id="adjustment-type" name="type"><option value="add">Add funds to budget</option><option value="withdraw">Withdraw funds from budget</option><option value="expense">Record external expense</option><option value="refund">Record external refund</option></select><div class="form-grid"><div><label for="adjustment-amount">Amount (CAD)</label><input id="adjustment-amount" name="amount" type="number" min="0.01" max="1000000" step="0.01" required></div><div><label for="adjustment-location">Location</label><select id="adjustment-location" name="location">${state.locations.map(l=>`<option>${l.name}</option>`).join('')}</select></div></div><label for="adjustment-date">Date</label><input id="adjustment-date" name="date" type="date" required value="${today()}"><label for="adjustment-reason">Reason / reference</label><textarea id="adjustment-reason" name="reason" required maxlength="1500" placeholder="e.g. Additional owner funding, rent paid outside ClearSpend…"></textarea><div class="context">Funds change the available budget. Expenses and refunds change actual spending and the chart. No real funds are moved.</div><div class="actions"><button class="primary">Save adjustment</button></div></form>`);$('#adjustment-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),reason=String(f.get('reason')).trim(),cost=Math.round(Number(f.get('amount'))*100);if(!reason||!Number.isFinite(cost)||cost<=0)return;const l=state.locations.find(l=>l.name===f.get('location'));const type=f.get('type');if(type==='withdraw'&&totals(l).budget<cost)return toast('A withdrawal cannot make the total budget negative.');state.adjustments??=[];state.adjustments.unshift({id:Date.now(),type,cost,location:l.name,date:f.get('date'),reason});persist();$('#modal').close();toast('Adjustment saved. Budget and spending updated.')}}

function historyRecordDate(r){return r.status==='Completed'||(r.status==='Removed'&&r.previousStatus==='Completed')?(r.purchasedOn||r.date):(r.requestedOn||r.date)}
function budgetAfterReversal(a){const location=state.locations.find(l=>l.name===a.location);const budget=totals(location).budget;return budget+(a.type==='add'?-a.cost:a.type==='withdraw'?a.cost:0)}
document.addEventListener('click',e=>{const picker=$('.history-status-picker[open]');if(picker&&!picker.contains(e.target))picker.open=false});
$('#modal').addEventListener('keydown',e=>{const picker=$('.history-status-picker[open]');if(e.key==='Escape'&&picker){e.preventDefault();e.stopPropagation();picker.open=false;picker.querySelector('summary').focus()}});
